    $catalog=Get-WsmCatalog $managerWorkspace $catalog.PairId
    Reject {Approve-WsmMigrationPlan -Workspace $managerWorkspace -PairId $catalog.PairId -TargetIdentityPath $targetPath -TargetIdentityHash ((Get-FileHash -LiteralPath $targetPath -Algorithm SHA256).Hash) -Path (Join-Path $root 'unselected-plan.json') -ExpectedRevision $catalog.DecisionRevision -PilotAcknowledgement 'ISOLATED-PILOT' -OfflineFullSet} 'seal rejects a workload mapping whose confirmed ExactMembers scope is no longer selected'
    $scopeSelection=@($catalog.Assistive.Selections.Items|Where-Object ItemId -CEQ $imported.ItemId)[0];$scopeSelection.Selected=$true
    $scope=@($catalog.Items|Where-Object ItemId -CEQ $imported.ItemId)[0];$scope.MigrationSpec.Members[0].SHA256=('0'*64);& $module {param($w,$p,$c) Write-WsmJson (Get-WsmCatalogPath $w $p) $c} $managerWorkspace $catalog.PairId $catalog
    $catalog=Get-WsmCatalog $managerWorkspace $catalog.PairId
    Reject {Approve-WsmMigrationPlan -Workspace $managerWorkspace -PairId $catalog.PairId -TargetIdentityPath $targetPath -TargetIdentityHash ((Get-FileHash -LiteralPath $targetPath -Algorithm SHA256).Hash) -Path (Join-Path $root 'tampered-plan.json') -ExpectedRevision $catalog.DecisionRevision -PilotAcknowledgement 'ISOLATED-PILOT' -OfflineFullSet} 'seal rejects a FileScope member hash changed after durable workload mapping review'
    Write-Output ('PASS Test-SourceCandidateMapping: '+$script:checks+' durable E0 mapping, CAS, dependency, draft, seal and package-reader checks.')
}finally{
    $temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')+'\';$resolved=[IO.Path]::GetFullPath($root);$name=[IO.Path]::GetFileName($resolved)
    if(-not $rootCreated -or [IO.Path]::GetDirectoryName($resolved).TrimEnd('\') -ine $temp.TrimEnd('\') -or $name -notmatch '^t-[A-Za-z0-9_-]{22}$' -or -not $resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase) -or $resolved -eq $temp.TrimEnd('\')){throw 'Refusing to clean a test directory outside its newly-created random temp root.'}
    if([IO.Directory]::Exists($resolved)){if(([IO.File]::GetAttributes($resolved) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'Refusing to clean a reparse-point test root.'};Remove-Item -LiteralPath $resolved -Recurse -Force}
}
